import workcell

def call(*args):
 r=workcell.call(*args)
 print(' '.join(args),repr(r.text),r.data,flush=True)
 if not r.ok: raise RuntimeError(r.text)
 return r

tares={'J1':123.22,'J2':119.72,'J3':121.62}
for jar in tares:
 if jar!='J1':
  call('robot','pick',jar)
  call('robot','place','platform')
 for i in range(110):
  net=call('scale','read').data['gross_g']-tares[jar]
  deficit=250-net
  print('NET',jar,round(net,2),'DEFICIT',round(deficit,2),flush=True)
  if abs(deficit)<=0.15:
   call('checkweigher','check')
   break
  if deficit < -0.15: action='remove'
  elif deficit>64: action='bulk'
  elif deficit>13: action='coarse'
  elif deficit>1.4: action='fine'
  else: action='micro'
  call('robot',action if action=='remove' else 'dose',*(() if action=='remove' else (action,)))
 else: raise RuntimeError('Could not finish '+jar)
 if jar!='J3':
  call('robot','pick',jar)
  call('robot','place','rack')
call('station','status')
